#include <frmprocessor.h>
#include <memory>
#include <opencv2/imgproc.hpp>

/**
 * @class LogFrame
 * @brief A @ref CameraFrame generated by loading a logfile through @ref VisionLogReader
 */
class LogFrame : public CameraFrame {
private:
    /** @brief The cv::Mat frame that was read from the log */
	cv::Mat m_cvFrame;
public:
    /** @brief Create the @ref LogFrame from a cv::Mat */
	LogFrame(cv::Mat frame);

    /** @brief Get a reference to the cv::Mat in @ref m_cvFrame */
	cv::Mat& GetCVFrame();
};